#include <string>
#include <unordered_map>

class Solution {
public:
    std::string filterCharacters(std::string s, int k) {
        std::unordered_map<char, int> freq;
        for (char c : s) freq[c]++;

        std::string res = "";
        for (char c : s) {
            if (freq[c] >= k) res.push_back(c);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String filterCharacters(String s, int k) {
        Map<Character, Integer> freq = new HashMap<>();
        for (char c : s.toCharArray()) {
            freq.put(c, freq.getOrDefault(c, 0) + 1);
        }

        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (freq.get(c) >= k) {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}

var filterCharacters = function(s, k) {
    const freq = new Map();
    for (const c of s) {
        freq.set(c, (freq.get(c) || 0) + 1);
    }

    let res = '';
    for (const c of s) {
        if (freq.get(c) >= k) {
            res += c;
        }
    }
    return res;
};
